(553,25536,N'Operation of an FET and its d</sub>"}},"i":0}}]}''>Id-g</sub>"}},"i":0}}]}''>Vg curve. At first, when no gate voltage is applied, there are no inversion electrons in the channel, so the device is turned off. As gate voltage increases, the inversion electron density in the channel increases, the current increases, and the device turns on.',N'4/43/Threshold_formation_nowatermark.gif',NULL),
