select
	'('
	+ cast(qid as varchar(20))
	+ ',' + coalesce(cast(q_act as varchar(20)),'NULL')
	+ ',' + coalesce(cast(q_cat as varchar(20)),'NULL')
	+ ',' + coalesce('N''' + replace(qname,'''','''''') + '''','NULL')
	+ ',' + coalesce('N''' + replace(qdesc,'''','''''') + '''','NULL')
	+ ',' + coalesce(cast(qsort as varchar(20)),'NULL')
	+ ',' + coalesce('N''' + replace(qhref,'''','''''') + '''','NULL')
	+ '),'
from q
join act on q_act=actid
order by qid

