(25191,215,NULL,N'scanner',N'A device that converts a paper image into an electronic file that you can open and work with on your computer.',NULL,NULL),
(25192,215,NULL,N'solid state drive (SSD)',N'A hard drive without moving parts, and is faster and more durable than magnetic drives.',NULL,NULL),
(25193,215,NULL,N'speakers',N'Output devices used to convey audio output, such as music, voice, sound effects, or other sounds.',NULL,NULL),
(25194,215,NULL,N'stylus',N'A pen-shaped digital tool for making selections and entering information on a touchscreen.',NULL,NULL),
(25195,215,NULL,N'surge suppressor',N'A device that prevents power fluctuations from damaging electronic components.',NULL,NULL),
(25196,215,NULL,N'swap file',N'Data that cannot fit in RAM and uses an area of the hard disk called virtual memory. Also called a paging file.',NULL,NULL),
(25197,215,NULL,N'tablet',N'A small, flat computer with a touch-sensitive screen that accepts input from a digital pen, stylus, or your fingertip',NULL,NULL),
(25198,215,NULL,N'touchpad',N'A flat surface that is touch-sensitive, and you move your finger around the touchpad to move the pointer on the screen.',NULL,NULL),
(25199,215,NULL,N'touchscreen',N'A display that lets you touch areas of the screen to interact with software.',NULL,NULL),
(25200,215,NULL,N'trackball',N'A stationary pointing device with a ball anchored inside a casing, as well as two or more buttons.',NULL,NULL),
(25201,215,NULL,N'Unicode',N'A coding systems that represent text and symbols in computers, communications equipment, and other devices that use text.',NULL,NULL),
(25202,215,NULL,N'uninterruptable power supply (UPS)',N'A device that maintains power to computer equipment in case of an interruption in the primary electrical source.',NULL,NULL),
(25203,215,NULL,N'USB hub',N'An external device that contains many USB ports.',NULL,NULL),
(25204,215,NULL,N'video card',N'A circuit board that processes image signals.',NULL,NULL),
(25205,215,NULL,N'virtual memory',N'In Computer Concepts, the capability of an operating system to temporarily store data on a storage medium until it can be  “swapped” into RAM.',NULL,NULL),
(25206,215,NULL,N'voice synthesizer',N'Voice output that converts text to speech.',NULL,NULL),
(25207,215,NULL,N'volatile',N'Memory that loses its contents when power is removed.',NULL,NULL),
(25208,215,NULL,N'webcams',N'In Computer Concepts, a camera built-in to a computer, which is primarily used for videoconferencing, chatting, or online  gaming.',NULL,NULL),
(25209,215,NULL,N'wheel',N'A type of game controller that mirrors the functionality of a steering wheel in a vehicle.',NULL,NULL),
(25210,215,NULL,N'word size',N'Determines the speed at which data in a computer travels, also referred to as bus width.',NULL,NULL),
(25348,217,NULL,N'3D Secure',N'A standard protocol for securing credit card transactions over the Internet.',NULL,N'https://en.wikipedia.org/wiki/3-D_Secure'),
(25349,217,NULL,N'address bar',N'In Computer Concepts, the part of a browser window that displays the location of the current webpage.',NULL,N'https://en.wikipedia.org/wiki/Address_bar'),
(25350,217,NULL,N'app',N'Short for “application,” a computer program that performs specific tasks; also called a program.',NULL,N'https://en.wikipedia.org/wiki/Application_software'),
(25351,217,NULL,N'application',N'Software that lets users perform specific tasks; also called a program or an app.',NULL,N'https://en.wikipedia.org/wiki/Application_software'),
(25352,217,NULL,N'blogs',N'Short for web log, an informal website consisting of date- or time-stamped articles, or posts, in a diary or journal format.',NULL,N'https://en.wikipedia.org/wiki/Blog'),
(25353,217,NULL,N'Boolean operators',N'A character, word, or symbol that focuses a web search. Also called a search operator.',NULL,N'https://en.wikipedia.org/wiki/Boolean_search'),
(25354,217,NULL,N'breadcrumbs',N'A step in the path you follow to display a webpage',NULL,N'https://en.wikipedia.org/wiki/Breadcrumb_navigation'),
(25355,217,NULL,N'browser',N'A program, such as Microsoft Edge, that is designed to display webpages.',NULL,N'https://en.wikipedia.org/wiki/Web_browser'),
(25356,217,NULL,N'business-to-business (B2B)',N'E-commerce model in which businesses provide goods, information, and services to other businesses, such as advertising, credit, recruiting, sales and marketing, technical support, and training.',NULL,N'https://en.wikipedia.org/wiki/Business-to-business'),
(25357,217,NULL,N'business-to-consumer (B2C)',N'E-commerce model in which businesses provide goods and services to consumers; the most widespread example is online shopping.',NULL,N'https://en.wikipedia.org/wiki/Business-to-consumer'),
(25358,217,NULL,N'cache',N'A holding area where your browser keeps a copy of each webpage you view. This temporary storage area helps speed up processing time.',NULL,N'https://en.wikipedia.org/wiki/Web_cache'),
(25359,217,NULL,N'citation',N'In a research paper, a reference to a source; usually in parentheses at the end of a sentence.',NULL,N'https://en.wikipedia.org/wiki/Citation'),
(25360,217,NULL,N'citation style',N'In a formal reference to a published work such as a book, journal, magazine, or website, the sequence of elements and the punctuation between them; common citation styles include MLA, APA, or Chicago.',NULL,N'https://en.wikipedia.org/wiki/Citation'),
(25361,217,NULL,N'consumer-to-consumer (C2C)',N'E-commerce model in which consumers provide goods and services to other consumers; the most widespread example of this is online auctions.',NULL,N'https://en.wikipedia.org/wiki/Consumer-to-consumer'),
(25362,217,NULL,N'content aggregator',N'A website that gathers, organizes, and then distributes web content.',NULL,N'https://en.wikipedia.org/wiki/News_aggregator'),
(25363,217,NULL,N'cookies',N'A file created by a website and that stores information on your computer, such as your website preferences; also called a first-party cookie.',NULL,N'https://en.wikipedia.org/wiki/HTTP_cookie'),
(25364,217,NULL,N'copyright',N'An originator’s exclusive legal right to reproduce, publish, or sell intellectual property.',NULL,N'https://en.wikipedia.org/wiki/Copyright'),
(25365,217,NULL,N'crawlers',N'Software that combs the web to find webpages and add new data about them to a database. Also called spider.',NULL,N'https://en.wikipedia.org/wiki/Web_crawler'),
(25366,217,NULL,N'Creative Commons (CC)',N'A nonprofit organization that makes it easy for content creators to license and share their work by supplying easy-to-understand copyright licenses; the creator chooses the conditions under which the work can be used.',NULL,N'https://en.wikipedia.org/wiki/Creative_Commons'),
(25367,217,NULL,N'digital certificate',N'In Computer Concepts, a technology used to verify a user’s identity by using a digital key and that has been “signed” by a trusted third party. This third party verifies the owner and that the key belongs to that owner.',NULL,N'https://en.wikipedia.org/wiki/Public_key_certificate'),
(25368,217,NULL,N'digital rights management (DRM)',N'A collection of technologies used by software publishers and trade groups to fight software piracy and prevent unauthorized copying of digital content; includes authentication, certificates of authenticity, encryption, and digital watermarks.',NULL,N'https://en.wikipedia.org/wiki/Digital_rights_management'),
(25369,217,NULL,N'domain name',N'In Computer Concepts, the portion of a URL or email address that identifies one or more IP addresses, such as cengage.com.',NULL,N'https://en.wikipedia.org/wiki/Domain_name'),
(25370,217,NULL,N'e-commerce',N'Business transactions that occur over an electronic network such as the Internet.',NULL,N'https://en.wikipedia.org/wiki/E-commerce'),
(25371,217,NULL,N'electronic storefront',N'An e-commerce website selling products or services.',NULL,N'https://en.wikipedia.org/wiki/Online_shopping'),
(25372,217,NULL,N'encryption',N'A security method of “scrambling” information as it is transmitted over a network. Information is scrambled in such a way that it cannot be read unless the user possesses the “key” to unlock it back to a readable format.',NULL,N'https://en.wikipedia.org/wiki/Encryption'),
(25373,217,NULL,N'ethics',N'The moral principles that govern people’s behavior; many schools and other organizations post codes of conduct for computer use, which can help you make ethical decisions while using a computer.',NULL,N'https://en.wikipedia.org/wiki/Computer_ethics'),
(25374,217,NULL,N'fair use doctrine',N'Allows you to use a sentence or paragraph of text without permission if you include a citation to the original source.',NULL,N'https://en.wikipedia.org/wiki/Fair_use'),
(25375,217,NULL,N'general search engine',N'A nonspecialized search engine designed to find general results; general search engines include Google, Bing, and Yahoo!',NULL,N'https://en.wikipedia.org/wiki/Search_engine'),
(25376,217,NULL,N'hits',N'A list of matched results from an Internet search.',NULL,N'https://en.wikipedia.org/wiki/Search_engine_results_page'),
(25377,217,NULL,N'home page',N'The main webpage around which a website is built that opens every time you start a browser.',NULL,N'https://en.wikipedia.org/wiki/Home_page'),
(25378,217,NULL,N'hyperlinks',N'In Access, a data type for fields that store a link to a webpage, file, or email address.',NULL,N'https://en.wikipedia.org/wiki/Hyperlink'),
(25379,217,NULL,N'Hypertext Transfer Protocol (HTTP)',N'The most common way to transfer information around the web; when the URL for a webpage starts with http://, the web browser uses this protocol for transferring the information.',NULL,N'https://en.wikipedia.org/wiki/HTTP'),
(25380,217,NULL,N'Hypertext Transfer Protocol Secure (HTTPS)',N'A protocol used to make a secure connection to a computer; identified by the “https” prefix in a URL and often used by banks and retail stores.',NULL,N'https://en.wikipedia.org/wiki/HTTPS'),
(25381,217,NULL,N'index',N'In Access, a database object that is created based on a field or combination of fields. Also, a field property that keeps track of the order of the values in the field, and a list that relates field values to the records that contain those values.',NULL,N'https://en.wikipedia.org/wiki/Database_index'),
(25382,217,NULL,N'information literacy',N'The ability to find, evaluate, use, and communicate online information.',NULL,N'https://en.wikipedia.org/wiki/Information_literacy'),
(25383,217,NULL,N'intellectual property rights',N'Legal rights protecting those who create works such as photos, art, writing, inventions, and music.',NULL,N'https://en.wikipedia.org/wiki/Intellectual_property'),
(25384,217,NULL,N'Internet',N'A global collection of millions of computers linked together to share information.',NULL,N'https://en.wikipedia.org/wiki/Internet'),
(25385,217,NULL,N'Internet Engineering Task Force (IETF)',N'A nonprofit group that sets standards to allow devices, services, and applications to work together across the Internet.',NULL,N'https://en.wikipedia.org/wiki/Internet_Engineering_Task_Force'),
(25386,217,NULL,N'IP address',N'A unique number that identifies every computer on the Internet; consists of four sets of numbers from 0 to 255 separated by periods, or dots, as in 216.35.148.4.',NULL,N'https://en.wikipedia.org/wiki/IP_address'),
(25387,217,NULL,N'keywords',N'In Office, terms added to a file’s Document Properties that help locate the file in a search.',NULL,N'https://en.wikipedia.org/wiki/Tag_(metadata)'),
(25388,217,NULL,N'media sharing site',N'A website that enables members to manage media such as photos, videos, and music.',NULL,N'https://en.wikipedia.org/wiki/Media_sharing'),
(25389,217,NULL,N'navigate',N'In Computer Concepts, to move from one webpage to another in a browser.',NULL,N'https://en.wikipedia.org/wiki/Web_navigation'),
(25390,217,NULL,N'navigation bar',N'In a browser, a set of buttons or hyperlinks that allows visitors to move to any page within a website.',NULL,N'https://en.wikipedia.org/wiki/Navigation_bar'),
(25391,217,NULL,N'online social network',N'An online community where users can share their interests, ideas, stories, photos, music, and videos with other registered users via a social networking website, such as Facebook, Google Plus, Twitter, Instagram, or Snapchat.',NULL,N'https://en.wikipedia.org/wiki/Social_networking_service'),
(25392,217,NULL,N'paraphrase',N'To restate an idea using different words from the original; paraphrasing someone else’s idea still constitutes plagiarism, which is claiming someone else’s idea as your own.',NULL,N'https://en.wikipedia.org/wiki/Paraphrase'),
(25393,217,NULL,N'plagiarism',N'To copy or use someone else’s work and claim it as your own.',NULL,N'https://en.wikipedia.org/wiki/Plagiarism'),
(25394,217,NULL,N'portal',N'A website that combines pages from many sources and provides access to those pages. Also called web portal.',NULL,N'https://en.wikipedia.org/wiki/Web_portal'),
(25395,217,NULL,N'protocol',N'A standardized procedure used by computers to exchange information.',NULL,N'https://en.wikipedia.org/wiki/Communication_protocol'),
(25396,217,NULL,N'public domain',N'An item, such as a photo, that is available and accessible to the public without requiring permission to use, and therefore not subject to copyright.',NULL,N'https://en.wikipedia.org/wiki/Public_domain'),
(25397,217,NULL,N'query',N'In Access, an object that provides a spreadsheet-like view of data, similar to that in tables; it may provide the user with a subset of fields and/or records from one or more tables. Also, SQL commands that are used to retrieve data.',NULL,N'https://en.wikipedia.org/wiki/Database_query'),
(25398,217,NULL,N'search engines',N'In Computer Concepts, software used by search sites to locate relevant webpages by creating a simple query based on your search criteria and storing the collected data in a search database.',NULL,N'https://en.wikipedia.org/wiki/Search_engine'),
(25399,217,NULL,N'search operators',N'A character, word, or symbol that focuses a web search. Also called a Boolean operator.',NULL,N'https://en.wikipedia.org/wiki/Boolean_search'),
(25400,217,NULL,N'search tool',N'An electronic tool that finds online information based on criteria you specify or selections you make.',NULL,N'https://en.wikipedia.org/wiki/Search_engine'),
(25401,217,NULL,N'specialized search tools',N'A search tool that concentrates on specific resources, such as scholarly journals or the United States Congress.',NULL,N'https://en.wikipedia.org/wiki/Vertical_search'),
(25402,217,NULL,N'specialty search engine',N'A search engine that lets you search databases, news providers, podcasts, and other online information sources that general search engines do not always access.',NULL,N'https://en.wikipedia.org/wiki/Vertical_search'),
(25403,217,NULL,N'spiders',N'Software that combs the web to find webpages and add new data about them to the database. Also called crawler.',NULL,N'https://en.wikipedia.org/wiki/Web_crawler'),
